// Single source of truth for the Kidzo CI pipeline (generated by ci/bootstrap/new-project.mjs, then owned by this project).
// The Jenkinsfile, the stage runner, the pre-PR gate and the tests all read this file. Review it: it lists what "verified" means here.
import path from "node:path";
import { fileURLToPath } from "node:url";

export const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
export const RESULTS_DIR = path.join(REPO_ROOT, ".ci", "results");

/** Hosts that must NEVER be reachable from, or baked into, CI builds (production API, production database ...). Fill these in. */
export const PRODUCTION_HOSTS = ["ixolgnnlmswenjmwvxez.supabase.co"];

/** Inert values used for every CI build and test run. Use values that can never reach production (".invalid" never resolves). */
export const CI_BUILD_ENV = {
  VITE_SUPABASE_URL: "http://127.0.0.1:4010",
  VITE_SUPABASE_PUBLISHABLE_KEY: "ci-anon-key-not-a-real-credential",
  VITE_SUPABASE_PROJECT_ID: "ci",
};

/** Stage name -> how to run it. A stage is PASS only when every command exits 0. */
export const STAGES = {
  lint: {
    phase: "build", title: "ESLint (no new errors)",
    commands: [{ cmd: "node", args: ["ci/pipeline/run-lint.mjs"] }], // existing lint errors are in ci/verify/quality/lint-baseline.json; only NEW ones fail
  },
  build: {
    phase: "build", title: "Production build",
    commands: [{ cmd: "npm", args: ["run","build"], env: CI_BUILD_ENV }],
  },
  "unit-tests": {
    phase: "test", title: "Unit tests",
    commands: [{ cmd: "npm", args: ["run","test"], env: CI_BUILD_ENV }],
  },
  "trivy-deps": {
    phase: "test", title: "Trivy dependency scan",
    commands: [{ cmd: "node", args: ["ci/pipeline/run-trivy.mjs","deps"] }],
  },
  "trivy-secrets": {
    phase: "test", title: "Trivy + pattern secret scan",
    commands: [{ cmd: "node", args: ["ci/pipeline/run-trivy.mjs","secrets"] }, { cmd: "node", args: ["ci/pipeline/scan-credentials.mjs"] }],
  },
  "repo-policy": {
    phase: "build", title: "Repository policy",
    commands: [{ cmd: "node", args: ["ci/verify/quality/run.mjs","repo-policy"] }],
  },
  "code-standards": {
    phase: "build", title: "Code standards",
    commands: [{ cmd: "node", args: ["ci/verify/quality/run.mjs","standards"] }],
  },
  maintainability: {
    phase: "build", title: "Maintainability",
    commands: [{ cmd: "node", args: ["ci/verify/quality/run.mjs","maintainability"] }],
  },
  architecture: {
    phase: "build", title: "Architecture",
    commands: [{ cmd: "node", args: ["ci/verify/quality/run.mjs","architecture"] }],
  },
  database: {
    phase: "build", title: "Database migrations",
    commands: [{ cmd: "node", args: ["ci/verify/quality/run.mjs","database"] }],
  },
};

/** Every one of these must be PASS before an attestation is issued. */
export const REQUIRED_CHECKS = Object.keys(STAGES);

export const GITHUB_CHECK_NAME = "unimisk/verified";
